/** `sandbox`: simulatePayment, simulatePayout, activatePayoutDestination, simulateSubscription, simulateInvoice. */
export class SandboxResource extends APIResource {
  /**
   * Simulate a payer (sandbox)
   *
   * In the sandbox (and dev and test), makes up what a payer does to one of your
   * payments, so you can test every case without testnet coins. A simulated deposit
   * is pending at first and settles about 10 seconds later; from then on it is
   * processed like any deposit, with the same statuses, credits and webhooks.
   * Simulated money is never swept. In live this route doesn't exist: `404`.
   *
   *
   * `POST /sandbox/payments/{id}/simulate`
   */
  simulatePayment(id: string, body: SimulateRequest, options?: RequestOptions): APIPromise<Simulation> {
    return this._client.request<Simulation>({ method: "POST", path: "/sandbox/payments/{id}/simulate", pathParams: { id }, body, amounts: ["/amount"] }, options);
  }

  /**
   * Fail a payout (sandbox)
   *
   * In the sandbox, where payouts are simulated (sent at once, finished about 10
   * seconds later, and never on a chain), fails one of your payouts that hasn't
   * finished: one waiting or scheduled, or one within its 10 seconds of sending. Its
   * amount and fees return to your available balance, and `payout.failed` is sent,
   * with `failure_reason` `simulated_failure`. Where payouts are sent for real, this
   * route doesn't exist: `404`.
   *
   *
   * `POST /sandbox/payouts/{id}/simulate`
   */
  simulatePayout(id: string, body: SimulatePayoutRequest, options?: RequestOptions): APIPromise<Payout> {
    return this._client.request<Payout>({ method: "POST", path: "/sandbox/payouts/{id}/simulate", pathParams: { id }, body }, options);
  }

  /**
   * Activate a destination now (sandbox)
   *
   * In the sandbox, makes one of your destinations that still waits usable at once,
   * instead of 5 minutes after it was added, and queues the payouts that waited for
   * it. `destination.active` is sent. Where payouts are sent for real, this route
   * doesn't exist: `404`.
   *
   *
   * `POST /sandbox/payout-destinations/{id}/activate`
   */
  activatePayoutDestination(id: string, options?: RequestOptions): APIPromise<PayoutDestination> {
    return this._client.request<PayoutDestination>({ method: "POST", path: "/sandbox/payout-destinations/{id}/activate", pathParams: { id } }, options);
  }

  /**
   * Move a subscription's time (sandbox)
   *
   * In the sandbox (and dev and test), moves the subscription's whole timeline
   * earlier so that its next moment (`to: next`), or a named one, is now, then runs
   * its schedule at once: a year of renewals, reminders and dunning in a few calls.
   * In live this route doesn't exist: `404`.
   *
   *
   * `POST /sandbox/subscriptions/{id}/simulate`
   */
  simulateSubscription(id: string, body: SimulateSubscriptionRequest, options?: RequestOptions): APIPromise<Subscription> {
    return this._client.request<Subscription>({ method: "POST", path: "/sandbox/subscriptions/{id}/simulate", pathParams: { id }, body }, options);
  }

  /**
   * Pay an invoice (sandbox)
   *
   * In the sandbox (and dev and test), pays what remains of an open invoice: a
   * payment as the invoice's page makes one, in the given asset (the plan's own for
   * a price in an asset), then a simulated deposit of its amount. The payment
   * finishes about 10 seconds later, and the invoice with it. In live this route
   * doesn't exist: `404`.
   *
   *
   * `POST /sandbox/invoices/{id}/simulate`
   */
  simulateInvoice(id: string, body: SimulateInvoiceRequest, options?: RequestOptions): APIPromise<Payment> {
    return this._client.request<Payment>({ method: "POST", path: "/sandbox/invoices/{id}/simulate", pathParams: { id }, body }, options);
  }
}

/** The client's resources, one for each group of operations. */
export abstract class NowgateResources {
  readonly status: StatusResource;
  readonly assets: AssetsResource;
  readonly rates: RatesResource;
  readonly payments: PaymentsResource;
  readonly paymentLinks: PaymentLinksResource;
  readonly logos: LogosResource;
  readonly balances: BalancesResource;
  readonly payoutDestinations: PayoutDestinationsResource;
  readonly payouts: PayoutsResource;
  readonly payoutBatches: PayoutBatchesResource;
  readonly refunds: RefundsResource;
  readonly forwarding: ForwardingResource;
  readonly plans: PlansResource;
  readonly subscriptions: SubscriptionsResource;
  readonly invoices: InvoicesResource;
  readonly sandbox: SandboxResource;

  protected constructor(client: Requester) {
    this.status = new StatusResource(client);
    this.assets = new AssetsResource(client);
    this.rates = new RatesResource(client);
    this.payments = new PaymentsResource(client);
    this.paymentLinks = new PaymentLinksResource(client);
    this.logos = new LogosResource(client);
    this.balances = new BalancesResource(client);
    this.payoutDestinations = new PayoutDestinationsResource(client);
    this.payouts = new PayoutsResource(client);
    this.payoutBatches = new PayoutBatchesResource(client);
    this.refunds = new RefundsResource(client);
    this.forwarding = new ForwardingResource(client);
    this.plans = new PlansResource(client);
    this.subscriptions = new SubscriptionsResource(client);
    this.invoices = new InvoicesResource(client);
    this.sandbox = new SandboxResource(client);
  }
}
